export type HorizontalAnchor = "left" | "center" | "right";
export type VerticalAnchor = "top" | "middle" | "bottom";

export interface Anchor {
  horizontal: HorizontalAnchor;
  vertical: VerticalAnchor;
}

export class CellCanvas {
  private readonly cells: string[][];
  private anchor: Anchor = { horizontal: "left", vertical: "top" };

  constructor(
    private readonly width: number,
    private readonly height: number,
    private readonly emptyValue: string = "",
  ) {
    if (!Number.isSafeInteger(width) || width <= 0 || !Number.isSafeInteger(height) || height <= 0) {
      throw new RangeError("width and height must be positive safe integers");
    }
    if (typeof emptyValue !== "string") {
      throw new TypeError("emptyValue must be a string");
    }
    this.cells = Array.from({ length: height }, () => Array<string>(width).fill(emptyValue));
  }

  fillColumns(values: readonly string[]): void {
    if (!Array.isArray(values) || values.length === 0) {
      throw new TypeError("values must be a non-empty array of strings");
    }
    for (let index = 0; index < values.length; index += 1) {
      if (!Object.prototype.hasOwnProperty.call(values, index) || typeof values[index] !== "string") {
        throw new TypeError("values must be a non-empty array of strings");
      }
    }
    for (let x = 0; x < this.width; x += 1) {
      const index = Math.min(values.length - 1, Math.round((x * values.length) / this.width));
      const value = values[index];
      for (let y = 0; y < this.height; y += 1) {
        this.cells[y][x] = value;
      }
    }
  }

  setAnchor(horizontal: HorizontalAnchor, vertical: VerticalAnchor): void {
    if (horizontal !== "left" && horizontal !== "center" && horizontal !== "right") {
      throw new TypeError("invalid horizontal anchor");
    }
    if (vertical !== "top" && vertical !== "middle" && vertical !== "bottom") {
      throw new TypeError("invalid vertical anchor");
    }
    this.anchor = { horizontal, vertical };
  }

  getAnchor(): Anchor {
    return { ...this.anchor };
  }

  clearArea(x = 0, y = 0, width = this.width - x, height = this.height - y): void {
    const values = [x, y, width, height];
    if (values.some((value) => !Number.isSafeInteger(value) || value < 0)) {
      throw new RangeError("clear rectangle values must be non-negative safe integers");
    }
    if (x > this.width || y > this.height || width > this.width - x || height > this.height - y) {
      throw new RangeError("clear rectangle is outside the canvas");
    }
    for (let row = y; row < y + height; row += 1) {
      for (let column = x; column < x + width; column += 1) {
        this.cells[row][column] = this.emptyValue;
      }
    }
  }

  snapshot(): string[][] {
    return this.cells.map((row) => [...row]);
  }
}
